head.script:
// 테스트 설명, 유효성 값 설정
//  - 담당 범위 : 조건 3건 (embeddedInput 무시 / viewType=default 시 editModeEvent 적용 / checkbox·radio·button 편집 미진입)
//  - 설정값별 기본 동작(미설정·onclick·ondblclick) 은 _1 담당
scwin.tData = {
    "description" : "[column > P > editModeEventIcon]<br/>viewType='icon' 인 Column 을 편집 모드로 변경하기 위한 마우스 이벤트 종류를 설정합니다.",
    "validation" : [
        "Column 의 embeddedInput=true 이면 editModeEventIcon 속성은 무시됩니다.",
        "Column 의 viewType='default' 이면 editModeEvent 속성이 적용됩니다.",
        "Column 의 inputType='checkbox','radio','button' 이면 편집 모드로 변경되지 않습니다."
    ]
}



scwin.gVar = { "evt" : "", "icon" : "" }



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    //  Column editModeEvent 와 Column editModeEventIcon 을 서로 다른 값으로 두어야 어느 속성을 따르는지 구분된다.
    con_editModeEvent.setValue("onclick");
    con_editModeEventIcon.setValue("ondblclick");
    con_viewType.setValue("default");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  target1 : embeddedInput 비교용 (select·spinner 각각 viewType=icon 단독 / viewType=icon + embeddedInput=true)
//  target2 : viewType 비교용 (select·calendar·autoComplete·checkcombobox·spinner 각각 viewType=con 선택값(default/미설정) / viewType=icon)
//  target3 : checkbox·radio·button (viewType 미설정 / viewType=icon)
//  모든 Body Column 에 Column editModeEvent / editModeEventIcon 을 con 선택값으로 설정한다 (GridView 속성은 미설정).
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof target2 !== 'undefined' && target2) {
        target2.remove();
    }
    if (typeof target3 !== 'undefined' && target3) {
        target3.remove();
    }
    if (typeof dlt_bind1 !== 'undefined' && dlt_bind1) {
        $p.data.remove("dlt_bind1");
    }
    if (typeof dlt_bind2 !== 'undefined' && dlt_bind2) {
        $p.data.remove("dlt_bind2");
    }
    if (typeof dlt_bind3 !== 'undefined' && dlt_bind3) {
        $p.data.remove("dlt_bind3");
    }
    if (typeof dlt_code !== 'undefined' && dlt_code) {
        $p.data.remove("dlt_code");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    let cEvt = con_editModeEvent.getValue();
    let cIcon = con_editModeEventIcon.getValue();
    let cViewType = con_viewType.getValue();
    scwin.gVar.evt = cEvt;
    scwin.gVar.icon = cIcon;

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 모든 Body Column 에 Column editModeEvent=' + cEvt + ', Column editModeEventIcon=' + cIcon + ' 설정 (두 값을 다르게 선택). target2 의 _def Column 은 viewType=' + (cViewType === "" ? "미설정" : cViewType) + '\n[절차] 각 셀을 단일 클릭 / 더블 클릭 / 첫 클릭 후 잠시 뒤 재클릭으로 조작 (아이콘 셀은 아이콘이 아닌 텍스트 영역을 조작, 목록이 열리는 셀은 조작마다 Esc 로 닫고 다음 조작)\n[확인] 편집 모드 진입 시 결과창에 셀과 적용된 이벤트가 자동 출력됨. _emb Column 은 첫 클릭에 입력창 포커스가 출력됨 (편집 모드 진입 출력 없음)"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // 코드/라벨 DataList (select·autoComplete·checkcombobox itemset)
    let strCode = '';
    strCode += '<w2:dataList ' + strNameSpace + ' id="dlt_code" baseNode="list" repeatNode="map">';
    strCode += '<w2:columnInfo>';
    strCode += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strCode += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strCode += '</w2:columnInfo>';
    strCode += '<w2:data use="true"></w2:data>';
    strCode += '</w2:dataList>';
    $p.data.create(strCode);
    dlt_code.setJSON([
        { "code" : "A", "label" : "서울" },
        { "code" : "B", "label" : "부산" },
        { "code" : "C", "label" : "대구" }
    ], false);

    // target1 DataList
    let strDl1 = '';
    strDl1 += '<w2:dataList ' + strNameSpace + ' id="dlt_bind1" baseNode="list" repeatNode="map">';
    strDl1 += '<w2:columnInfo>';
    strDl1 += '<w2:column id="sel_icon" name="sel_icon" dataType="text"></w2:column>';
    strDl1 += '<w2:column id="sel_emb" name="sel_emb" dataType="text"></w2:column>';
    strDl1 += '<w2:column id="spn_icon" name="spn_icon" dataType="text"></w2:column>';
    strDl1 += '<w2:column id="spn_emb" name="spn_emb" dataType="text"></w2:column>';
    strDl1 += '</w2:columnInfo>';
    strDl1 += '<w2:data use="true"></w2:data>';
    strDl1 += '</w2:dataList>';
    $p.data.create(strDl1);
    dlt_bind1.setJSON([
        { "sel_icon" : "A", "sel_emb" : "A", "spn_icon" : "5", "spn_emb" : "5" },
        { "sel_icon" : "B", "sel_emb" : "B", "spn_icon" : "10", "spn_emb" : "10" },
        { "sel_icon" : "C", "sel_emb" : "C", "spn_icon" : "15", "spn_emb" : "15" }
    ], false);

    // target2 DataList
    let strDl2 = '';
    strDl2 += '<w2:dataList ' + strNameSpace + ' id="dlt_bind2" baseNode="list" repeatNode="map">';
    strDl2 += '<w2:columnInfo>';
    strDl2 += '<w2:column id="sel_def" name="sel_def" dataType="text"></w2:column>';
    strDl2 += '<w2:column id="sel_icon" name="sel_icon" dataType="text"></w2:column>';
    strDl2 += '<w2:column id="cal_def" name="cal_def" dataType="date"></w2:column>';
    strDl2 += '<w2:column id="cal_icon" name="cal_icon" dataType="date"></w2:column>';
    strDl2 += '<w2:column id="ac_def" name="ac_def" dataType="text"></w2:column>';
    strDl2 += '<w2:column id="ac_icon" name="ac_icon" dataType="text"></w2:column>';
    strDl2 += '<w2:column id="ccb_def" name="ccb_def" dataType="text"></w2:column>';
    strDl2 += '<w2:column id="ccb_icon" name="ccb_icon" dataType="text"></w2:column>';
    strDl2 += '<w2:column id="spn_def" name="spn_def" dataType="text"></w2:column>';
    strDl2 += '<w2:column id="spn_icon" name="spn_icon" dataType="text"></w2:column>';
    strDl2 += '</w2:columnInfo>';
    strDl2 += '<w2:data use="true"></w2:data>';
    strDl2 += '</w2:dataList>';
    $p.data.create(strDl2);
    dlt_bind2.setJSON([
        { "sel_def" : "A", "sel_icon" : "A", "cal_def" : "20260115", "cal_icon" : "20260115", "ac_def" : "A", "ac_icon" : "A", "ccb_def" : "A B", "ccb_icon" : "A B", "spn_def" : "5", "spn_icon" : "5" },
        { "sel_def" : "B", "sel_icon" : "B", "cal_def" : "20260220", "cal_icon" : "20260220", "ac_def" : "B", "ac_icon" : "B", "ccb_def" : "B C", "ccb_icon" : "B C", "spn_def" : "10", "spn_icon" : "10" },
        { "sel_def" : "C", "sel_icon" : "C", "cal_def" : "20260312", "cal_icon" : "20260312", "ac_def" : "C", "ac_icon" : "C", "ccb_def" : "A C", "ccb_icon" : "A C", "spn_def" : "15", "spn_icon" : "15" }
    ], false);

    // target3 DataList
    let strDl3 = '';
    strDl3 += '<w2:dataList ' + strNameSpace + ' id="dlt_bind3" baseNode="list" repeatNode="map">';
    strDl3 += '<w2:columnInfo>';
    strDl3 += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDl3 += '<w2:column id="chk_icon" name="chk_icon" dataType="text"></w2:column>';
    strDl3 += '<w2:column id="rad" name="rad" dataType="text"></w2:column>';
    strDl3 += '<w2:column id="rad_icon" name="rad_icon" dataType="text"></w2:column>';
    strDl3 += '<w2:column id="btn" name="btn" dataType="text"></w2:column>';
    strDl3 += '<w2:column id="btn_icon" name="btn_icon" dataType="text"></w2:column>';
    strDl3 += '</w2:columnInfo>';
    strDl3 += '<w2:data use="true"></w2:data>';
    strDl3 += '</w2:dataList>';
    $p.data.create(strDl3);
    dlt_bind3.setJSON([
        { "chk" : "1", "chk_icon" : "1", "rad" : "1", "rad_icon" : "1", "btn" : "상세", "btn_icon" : "상세" },
        { "chk" : "0", "chk_icon" : "0", "rad" : "0", "rad_icon" : "0", "btn" : "상세", "btn_icon" : "상세" },
        { "chk" : "1", "chk_icon" : "1", "rad" : "0", "rad_icon" : "0", "btn" : "상세", "btn_icon" : "상세" }
    ], false);

    let grp_comp = $c.gcm.getTestGroup();
    let evtAttr = ' editModeEvent="' + cEvt + '" editModeEventIcon="' + cIcon + '"';
    let defAttr = (cViewType === "" ? "" : ' viewType="' + cViewType + '"');
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_code"><w2:label ref="label"></w2:label><w2:value ref="code"></w2:value></w2:itemset></w2:choices>';
    let calAttr = ' dataType="date" calendarValueType="yearMonthDate" displayFormat="yyyy-MM-dd"';

    // target1 : viewType=icon 단독 / viewType=icon + embeddedInput=true
    let strTarget1 = '';
    strTarget1 += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind1" checkAllType="false" ev:onbeforeedit="scwin.target1_onbeforeedit" id="" style="width:600px;height:170px;">';
    strTarget1 += '<w2:header style="" id="header1">';
    strTarget1 += '<w2:row style="" id="hrow1">';
    strTarget1 += '<w2:column width="150" inputType="text" id="hsel_icon" value="sel_icon (select)"></w2:column>';
    strTarget1 += '<w2:column width="150" inputType="text" id="hsel_emb" value="sel_emb (select)"></w2:column>';
    strTarget1 += '<w2:column width="150" inputType="text" id="hspn_icon" value="spn_icon (spinner)"></w2:column>';
    strTarget1 += '<w2:column width="150" inputType="text" id="hspn_emb" value="spn_emb (spinner)"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:header>';
    strTarget1 += '<w2:gBody style="" id="gBody1">';
    strTarget1 += '<w2:row style="" id="brow1">';
    strTarget1 += '<w2:column width="150" inputType="select" viewType="icon" dataType="text" id="sel_icon"' + evtAttr + '>' + itemset + '</w2:column>';
    strTarget1 += '<w2:column width="150" inputType="select" viewType="icon" embeddedInput="true" dataType="text" id="sel_emb"' + evtAttr + '>' + itemset + '</w2:column>';
    strTarget1 += '<w2:column width="150" inputType="spinner" viewType="icon" dataType="text" id="spn_icon"' + evtAttr + '></w2:column>';
    strTarget1 += '<w2:column width="150" inputType="spinner" viewType="icon" embeddedInput="true" dataType="text" id="spn_emb"' + evtAttr + '></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:gBody>';
    strTarget1 += '</w2:gridView>';
    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget1, grp_comp);

    // target2 : 같은 inputType 을 viewType=con 선택값(default/미설정) 과 viewType=icon 으로 쌍 구성
    let strTarget2 = '';
    strTarget2 += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind2" checkAllType="false" ev:onbeforeedit="scwin.target2_onbeforeedit" id="" style="width:1010px;height:170px;margin-top:10px;">';
    strTarget2 += '<w2:header style="" id="header2">';
    strTarget2 += '<w2:row style="" id="hrow2">';
    strTarget2 += '<w2:column width="100" inputType="text" id="hsel_def" value="sel_def"></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="text" id="hsel_icon2" value="sel_icon"></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="text" id="hcal_def" value="cal_def"></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="text" id="hcal_icon" value="cal_icon"></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="text" id="hac_def" value="ac_def"></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="text" id="hac_icon" value="ac_icon"></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="text" id="hccb_def" value="ccb_def"></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="text" id="hccb_icon" value="ccb_icon"></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="text" id="hspn_def" value="spn_def"></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="text" id="hspn_icon2" value="spn_icon"></w2:column>';
    strTarget2 += '</w2:row>';
    strTarget2 += '</w2:header>';
    strTarget2 += '<w2:gBody style="" id="gBody2">';
    strTarget2 += '<w2:row style="" id="brow2">';
    strTarget2 += '<w2:column width="100" inputType="select"' + defAttr + ' dataType="text" id="sel_def"' + evtAttr + '>' + itemset + '</w2:column>';
    strTarget2 += '<w2:column width="100" inputType="select" viewType="icon" dataType="text" id="sel_icon"' + evtAttr + '>' + itemset + '</w2:column>';
    strTarget2 += '<w2:column width="100" inputType="calendar"' + defAttr + calAttr + ' id="cal_def"' + evtAttr + '></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="calendar" viewType="icon"' + calAttr + ' id="cal_icon"' + evtAttr + '></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="autoComplete"' + defAttr + ' dataType="text" id="ac_def"' + evtAttr + '>' + itemset + '</w2:column>';
    strTarget2 += '<w2:column width="100" inputType="autoComplete" viewType="icon" dataType="text" id="ac_icon"' + evtAttr + '>' + itemset + '</w2:column>';
    strTarget2 += '<w2:column width="100" inputType="checkcombobox"' + defAttr + ' dataType="text" id="ccb_def"' + evtAttr + '>' + itemset + '</w2:column>';
    strTarget2 += '<w2:column width="100" inputType="checkcombobox" viewType="icon" dataType="text" id="ccb_icon"' + evtAttr + '>' + itemset + '</w2:column>';
    strTarget2 += '<w2:column width="100" inputType="spinner"' + defAttr + ' dataType="text" id="spn_def"' + evtAttr + '></w2:column>';
    strTarget2 += '<w2:column width="100" inputType="spinner" viewType="icon" dataType="text" id="spn_icon"' + evtAttr + '></w2:column>';
    strTarget2 += '</w2:row>';
    strTarget2 += '</w2:gBody>';
    strTarget2 += '</w2:gridView>';
    scwin.target2 = await $p.dynamicCreate("target2", "gridView", strTarget2, grp_comp);

    // target3 : checkbox·radio·button (viewType 미설정 / viewType=icon)
    let strTarget3 = '';
    strTarget3 += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind3" checkAllType="false" ev:onbeforeedit="scwin.target3_onbeforeedit" id="" style="width:720px;height:170px;margin-top:10px;">';
    strTarget3 += '<w2:header style="" id="header3">';
    strTarget3 += '<w2:row style="" id="hrow3">';
    strTarget3 += '<w2:column width="120" inputType="text" id="hchk" value="chk (checkbox)"></w2:column>';
    strTarget3 += '<w2:column width="120" inputType="text" id="hchk_icon" value="chk_icon (checkbox)"></w2:column>';
    strTarget3 += '<w2:column width="120" inputType="text" id="hrad" value="rad (radio)"></w2:column>';
    strTarget3 += '<w2:column width="120" inputType="text" id="hrad_icon" value="rad_icon (radio)"></w2:column>';
    strTarget3 += '<w2:column width="120" inputType="text" id="hbtn" value="btn (button)"></w2:column>';
    strTarget3 += '<w2:column width="120" inputType="text" id="hbtn_icon" value="btn_icon (button)"></w2:column>';
    strTarget3 += '</w2:row>';
    strTarget3 += '</w2:header>';
    strTarget3 += '<w2:gBody style="" id="gBody3">';
    strTarget3 += '<w2:row style="" id="brow3">';
    strTarget3 += '<w2:column width="120" inputType="checkbox" dataType="text" trueValue="1" falseValue="0" valueType="other" id="chk"' + evtAttr + '></w2:column>';
    strTarget3 += '<w2:column width="120" inputType="checkbox" viewType="icon" dataType="text" trueValue="1" falseValue="0" valueType="other" id="chk_icon"' + evtAttr + '></w2:column>';
    strTarget3 += '<w2:column width="120" inputType="radio" dataType="text" trueValue="1" falseValue="0" valueType="other" id="rad"' + evtAttr + '></w2:column>';
    strTarget3 += '<w2:column width="120" inputType="radio" viewType="icon" dataType="text" trueValue="1" falseValue="0" valueType="other" id="rad_icon"' + evtAttr + '></w2:column>';
    strTarget3 += '<w2:column width="120" inputType="button" dataType="text" id="btn"' + evtAttr + '></w2:column>';
    strTarget3 += '<w2:column width="120" inputType="button" viewType="icon" dataType="text" id="btn_icon"' + evtAttr + '></w2:column>';
    strTarget3 += '</w2:row>';
    strTarget3 += '</w2:gBody>';
    strTarget3 += '</w2:gridView>';
    scwin.target3 = await $p.dynamicCreate("target3", "gridView", strTarget3, grp_comp);

    // embeddedInput 셀은 편집 모드 전환 없이 입력창이 상시 표시되므로 입력창 포커스 시점을 출력한다.
    // validation 1 판정 출력
    let embInputs = target1.render.querySelectorAll("td[col_id$='_emb'] input, td[col_id$='_emb'] select, td[data-col_id$='_emb'] input, td[data-col_id$='_emb'] select");
    for (let i = 0; i < embInputs.length; i++) {
        embInputs[i].addEventListener("focus", scwin.embInput_onfocus);
    }
}



// 셀에 기록된 편집 트리거 이벤트가 어느 Column 속성값인지 표기
scwin.getEvtSource = function (evt) {
    if (evt === scwin.gVar.icon && evt !== scwin.gVar.evt) {
        return evt + " (editModeEventIcon)";
    }
    if (evt === scwin.gVar.evt && evt !== scwin.gVar.icon) {
        return evt + " (editModeEvent)";
    }
    return evt;
}



// 편집 모드 진입 시 셀과 그 셀에 적용된 편집 트리거 이벤트 출력
//  onbeforeedit 는 편집 모드로 바뀌지 않는 셀(button, embeddedInput)에서도 발생하므로,
//  이벤트 처리 후 isEditing() 이 true 인 경우에만 편집 모드 진입으로 출력한다.
scwin.printEdit = function (grid, rowIndex, columnIndex) {
    let colId = grid.getColumnID(columnIndex);
    setTimeout(function () {
        if (!grid.isEditing()) {
            return;
        }
        let td = grid.render.querySelector("td[id$='_cell_" + rowIndex + "_" + columnIndex + "']");
        let evt = td ? (td.getAttribute("data-editModeEvent") || "") : "";
        wf_body_bottom.getObj("scwin").setReturnValue(
            "편집 모드 진입 : " + grid.getID().replace("mf_", "") + " " + colId + " Row " + rowIndex + " | 적용 이벤트 = " + scwin.getEvtSource(evt));
    }, 0);
}



// validation 1 판정 출력 (sel_icon·spn_icon 대조군)
scwin.target1_onbeforeedit = function (rowIndex, columnIndex, value) {
    scwin.printEdit(scwin.target1, rowIndex, columnIndex);
}



// validation 2 판정 출력
scwin.target2_onbeforeedit = function (rowIndex, columnIndex, value) {
    scwin.printEdit(scwin.target2, rowIndex, columnIndex);
}



// validation 3 판정 출력 (checkbox/radio/button 은 출력되지 않아야 함)
scwin.target3_onbeforeedit = function (rowIndex, columnIndex, value) {
    scwin.printEdit(scwin.target3, rowIndex, columnIndex);
}



// validation 1 판정 출력 : embeddedInput 셀은 editModeEventIcon 설정값과 관계없이 클릭 즉시 입력창에 포커스되어 바로 입력 가능
scwin.embInput_onfocus = function (e) {
    let td = e.target.closest("td[id*='_cell_']");
    let rowIndex = td ? td.id.split("_cell_")[1].split("_")[0] : "";
    let colId = td ? (td.getAttribute("col_id") || td.getAttribute("data-col_id") || "") : "";
    wf_body_bottom.getObj("scwin").setReturnValue(
        colId + " Row " + rowIndex + " 입력창 포커스 (editModeEventIcon=" + scwin.gVar.icon + " 설정) -> 바로 입력 가능");
}
